    /** M3TokenEngine.findAllSpans#1 SCENARIO; oracle: java.util.regex(region-span-set). */
    static void findAllSpans() throws Throwable {
        MethodHandle atom = ev("findAllSpans", MethodType.methodType(RESULT));
        for (boolean safe : new boolean[] {true, false}) {
            for (String pattern : patterns(safe)) {
                for (String letters : tapes()) {
                    Object engine = engine(pattern, TokenRegexOracle.tape(letters, false), false);
                    int n = letters.length();
                    TreeSet<Integer> spans = new TreeSet<>();
                    int lastStart = -1;
                    Map<Integer, Integer> firstEnd = new LinkedHashMap<>();
                    for (int[] r = regs(atom.invoke(engine)); r != null; r = regs(atom.invoke(engine))) {
                        assertTrue(r[0] >= lastStart, "starts never decrease");
                        lastStart = r[0];
                        assertTrue(spans.add(r[0] * (n + 1) + r[1]), "distinct spans");
                        firstEnd.putIfAbsent(r[0], r[1]);
                    }
                    assertEquals(TokenRegexOracle.javaSpans(pattern, letters), spans, pattern + " / " + letters);
                    if (safe) {
                        Matcher m = TokenRegexOracle.javaMatcher(pattern, letters);
                        for (Map.Entry<Integer, Integer> e : firstEnd.entrySet()) {
                            m.region(e.getKey(), n);
                            assertTrue(m.lookingAt());
                            assertEquals(m.end(), (int) e.getValue(), "priority of start " + e.getKey() + " " + pattern + " / " + letters);
                        }
                    }
                }
            }
        }
    }

    /** M3TokenEngine.findNext#1 SCENARIO; oracle: java.util.regex.Matcher.find. */
    static void findNext() throws Throwable {
        MethodHandle atom = ev("findNext", MethodType.methodType(RESULT));
        for (boolean safe : new boolean[] {true, false}) {
            for (String pattern : patterns(safe)) {
                for (String letters : tapes()) {
                    Object engine = engine(pattern, TokenRegexOracle.tape(letters, false), false);
                    Matcher m = TokenRegexOracle.javaMatcher(pattern, letters);
                    if (!safe) {
                        int[] first = regs(atom.invoke(engine));
                        boolean found = m.find();
                        assertEquals(found, first != null, pattern + " / " + letters);
                        if (found) assertEquals(m.start(), first[0], "leftmost start " + pattern + " / " + letters);
                        continue;
                    }
                    List<int[]> expected = new ArrayList<>();
                    while (m.find()) expected.add(javaRegisters(m));
                    List<int[]> got = new ArrayList<>();
                    for (int[] r = regs(atom.invoke(engine)); r != null; r = regs(atom.invoke(engine))) got.add(r);
                    assertEquals(expected.size(), got.size(), "match count " + pattern + " / " + letters);
                    for (int i = 0; i < got.size(); i++) assertArrayEquals(expected.get(i), got.get(i), pattern + " / " + letters + " #" + i);
                }
            }
        }
    }

    /** M3TokenEngine.evaluateRoot#1 SCENARIO; oracle: java.util.regex(ends-per-start). */
    static void evaluateRoot() throws Throwable {
        MethodHandle atom = ev("evaluateRoot", MethodType.methodType(STATES, int.class));
        for (String pattern : patterns(false)) {
            for (String letters : tapes()) {
                Object engine = engine(pattern, TokenRegexOracle.tape(letters, false), false);
                for (int start = 0; start <= letters.length(); start++) {
                    int[] ends = positions(atom.invoke(engine, start));
                    TreeSet<Integer> got = new TreeSet<>();
                    for (int e : ends) assertTrue(got.add(e), "endpoints are deduplicated");
                    assertEquals(javaEnds(pattern, letters, start), got, pattern + " / " + letters + " @" + start);
                }
            }
        }
    }

