    /** M3TokenEngine.alternative#1 SCENARIO; oracle: written-order-union. */
    static void alternative() throws Throwable {
        TokenRegexOracle.Tape tape = TokenRegexOracle.tape("abc", false);
        String pattern = "(a b | a | a b c)";
        Object engine = engine(pattern, tape, false);
        ev("evaluateRoot", MethodType.methodType(STATES, int.class)).invoke(engine, 0);
        M3TokenPattern compiled = M3TokenPattern.compile(pattern);
        int group = compiled.rootNode();
        int alt = compiled.nodeX(group);
        MethodHandle atom = ev("alternative", MethodType.methodType(STATES, int.class, int.class, int[].class));
        assertEquals(M3TokenPattern.N_ALT, compiled.nodeOp(alt));
        assertArrayEquals(new int[] {2, 1, 3}, positions(atom.invoke(engine, alt, 0, fill(stride(pattern)))), "branches in written order");
        int[] shared = fill(stride(pattern));
        int[] before = shared.clone();
        atom.invoke(engine, alt, 0, shared);
        assertArrayEquals(before, shared, "caller registers are not modified");
        TokenRegexOracle.Tape one = TokenRegexOracle.tape("a", false);
        M3TokenMatcher m = M3TokenMatcher.of(TokenRegexOracle.bind("((?<x> a) b | a)", one), M3TokenMatcher.FIND_NEXT, false);
        assertTrue(m.matches());
        assertEquals(-1, m.start("x"), "a group of a failed first branch does not leak into the second (regression)");
        assertEquals(-1, m.end("x"));
        Matcher java = TokenRegexOracle.javaMatcher("((?<x> a) b | a)", "a");
        assertTrue(java.matches());
        assertEquals(java.start("x"), m.start("x"));
    }

