    /** M3TokenEngine.repeat#1 SCENARIO; oracle: greedy-deep-first+reluctant-shallow-first. */
    static void repeat() throws Throwable {
        TokenRegexOracle.Tape tape = TokenRegexOracle.tape("abab", false);
        MethodHandle atom = ev("repeat", MethodType.methodType(STATES, int.class, int.class, int[].class));
        for (String[] c : new String[][] {{"(a | a b)*", "3,4,1,2,0"}, {"(a | a b)*?", "0,1,2,3,4"}, {"(a b){1,2}", "4,2"},
                {"(a b){1,2}?", "2,4"}, {"(a b){3,}", ""}}) {
            Object engine = engine(c[0], tape, false);
            ev("evaluateRoot", MethodType.methodType(STATES, int.class)).invoke(engine, 0);
            int node = M3TokenPattern.compile(c[0]).rootNode();
            assertEquals(M3TokenPattern.N_REPEAT, M3TokenPattern.compile(c[0]).nodeOp(node));
            int[] expected = c[1].isEmpty() ? new int[0] : Arrays.stream(c[1].split(",")).mapToInt(Integer::parseInt).toArray();
            assertArrayEquals(expected, positions(atom.invoke(engine, node, 0, fill(stride(c[0])))), c[0]);
        }
    }

